interface Flyable { String fly(); }
interface Mappable { String map(); }
class SurveyDrone implements Flyable, Mappable {
    public String fly() { return "fly"; }
    public String map() { return "map"; }
}
public class MultipleInterfaceInheritanceDemo {
    public static void main(String[] args) { var d = new SurveyDrone(); System.out.println(d.fly() + " " + d.map()); }
}
